  // ------------------------------------------------------------------ map
  var map = L.map("map", { zoomSnap: 0.25, minZoom: 8, maxZoom: 16, worldCopyJump: false, zoomControl: false, fadeAnimation: false });
  L.control.zoom({ position: "topright", zoomInTitle: "확대", zoomOutTitle: "축소" }).addTo(map);
  map.attributionControl.setPrefix(false);
  map.createPane("choro").style.zIndex = 400;
  map.createPane("outline").style.zIndex = 410;
  map.createPane("reg").style.zIndex = 420;
  map.createPane("sel").style.zIndex = 425;
  map.createPane("rail").style.zIndex = 430;
  map.createPane("labels").style.zIndex = 450;
  ["outline", "reg", "sel", "labels"].forEach(function (p) { map.getPane(p).style.pointerEvents = "none"; });
  map.attributionControl.addAttribution("경계 © 통계청 SGIS (vuski/admdongkor 가공, CC BY 4.0) · 역·한강·지명검색 © OpenStreetMap contributors");
