    if (shape === "square") el = s("rect", { x: c - r * 0.92, y: c - r * 0.92, width: r * 1.84, height: r * 1.84, rx: 1.5 });
    else if (shape === "diamond") el = s("polygon", { points: [c, c - r * 1.22, c + r * 1.22, c, c, c + r * 1.22, c - r * 1.22, c].join(",") });
    else if (shape === "triangle") el = s("polygon", { points: [c, c - r * 1.15, c + r * 1.1, c + r * 0.8, c - r * 1.1, c + r * 0.8].join(",") });
