  // ------------------------------------------------------------------ 맞춤 찾기 (goal-first finder)
  // Purposes come from complex_scores.meta, the visitor's situation lives in SIT (memory only unless
  // they tick "이 기기에 저장"), and money questions go through window.APT_FIN over policy_rules.
  // Everything that depends on a data file is feature-detected; missing files hide their UI.
  var CS = DATA.complex_scores && DATA.complex_scores.items && DATA.complex_scores.meta ? DATA.complex_scores : null;
  var FIN = window.APT_FIN || null;
  var PR = FIN && DATA.policy_rules && DATA.policy_rules.mortgage && DATA.policy_rules.purchase_costs ? DATA.policy_rules : null;
  var CSM = CS ? CS.meta : {};
  var CS_ITEMS = CS ? CS.items : [];
  var CS_AREAS = CS ? (CS.areas || []) : [];
  var csById = {};
  CS_ITEMS.forEach(function (it) { csById[it.id] = it; });
  function isNum(v) { return typeof v === "number" && isFinite(v); }
  function sum(list, fn) { return list.reduce(function (a, x) { return a + fn(x); }, 0); }
  var GROUPS = CSM.groups || [];
  function groupId(p) { var g = GROUPS.filter(function (x) { return x.id === p.group || x.label === p.group; })[0]; return g ? g.id : p.group; }
  var PURPOSES = (CSM.purposes || []).map(function (p) { return Object.assign({}, p, { gid: groupId(p) }); });
  var purposeById = {};
  PURPOSES.forEach(function (p) { purposeById[p.id] = p; });
  var JC = (CSM.job_centres || []).filter(function (j) { return purposeById["commute_" + j.id]; });
  function jcShort(j) { return String(j.label || j.id).replace(/역$/, ""); }
  // the four fixed commute purposes collapse into one "출퇴근" chip
  var DISPLAY = [], COMMUTE = null;
  PURPOSES.forEach(function (p) {
    if (/^commute_/.test(p.id)) {
      if (!COMMUTE) {
        COMMUTE = { id: "commute", label: "출퇴근", gid: p.gid, virtual: true,
          description: "직장까지 걸리는 시간. 내 직장을 고르면 그곳까지, 아니면 강남·여의도·판교·광화문 중 고른 곳까지의 시간으로 계산합니다.",
          formula: p.formula, caveats: p.caveats };
        DISPLAY.push(COMMUTE);
      }
      return;
    }
    DISPLAY.push(p);
  });
  var displayById = {};
  DISPLAY.forEach(function (p) { displayById[p.id] = p; });
  function pLabel(pid) { return (displayById[pid] || purposeById[pid] || {}).label || pid; }
  var QUICK = [
    { id: "invest", label: "투자 우선", w: { invest: 2, newrail: 1, rebuild: 1 } },
    { id: "kids", label: "아이 키우기", w: { edu: 2, park: 1, hospital: 1, bigcomplex: 1 } },
    { id: "rebuild", label: "재건축 기다리기", w: { rebuild: 2, invest: 1, value: 1 } },
    { id: "first", label: "첫 집·예산 빠듯", w: { value: 2, lowreg: 1, station: 1 } },
    { id: "transit", label: "교통 최우선", w: { station: 2, commute: 2, newrail: 1 } }
  ].map(function (q) { var w = {}; Object.keys(q.w).forEach(function (k) { if (displayById[k]) w[k] = q.w[k]; }); return Object.assign(q, { w: w }); });

  // ---- places (hubs) and travel times
  var HUBS_REAL = CS && Array.isArray(CS.hubs) && CS.hubs.length ? CS.hubs.filter(function (x) { return x && x.id && x.name; }) : null;
  var HUBS = HUBS_REAL || JC.map(function (j) { return { id: "jc-" + j.id, name: j.label, kind: "업무지구", lat: j.lat, lng: j.lng, station: j.label, _jc: j.id }; });
  var hubById = {};
  HUBS.forEach(function (x) { hubById[x.id] = x; });
  function travelOf(o, hubId) {
    var hb = hubById[hubId];
    if (!hb || !o) return null;
    var t = o.travel && o.travel[hubId];
    if (t && isNum(t.transit_min)) return { min: t.transit_min, mode: "transit", note: t.transit_note || null };
    if (t && isNum(t.drive_min)) return { min: t.drive_min, mode: "drive" };
    if (hb._jc && o.attributes) { var d = o.attributes["drive_" + hb._jc]; if (d && isNum(d.value)) return { min: d.value, mode: "drive" }; }
    return null;
  }
  function travelText(t) { return !t ? "시간 자료 없음" : (t.mode === "transit" ? "전철 약 " : "차로 ") + Math.round(t.min) + "분"; }
  function driveOf(o, hubId) { var t = o && o.travel && o.travel[hubId]; return t && isNum(t.drive_min) ? t.drive_min : null; }
  function transitModelText() {
    if (CSM.transit_note) return CSM.transit_note;
    var m = CSM.transit_model;
    if (!m) return null;
    return typeof m === "string" ? m : m.note || m.summary || m.description || null;
  }
  var anyTransit = CS_ITEMS.some(function (it) { return it.travel && Object.keys(it.travel).some(function (k) { return isNum(it.travel[k].transit_min); }); });
  var BP_DRIVE = (function () {
    var p = purposeById.commute_gangnam, bp = p && p.breakpoints;
    var first = bp && Object.keys(bp).map(function (k) { return bp[k]; })[0];
    return Array.isArray(first) && first.length >= 2 ? first : [[10, 100], [50, 0]];
  })();
  var BP_TRANSIT = [[20, 100], [90, 0]];
  function pw(x, bp) {
    if (x <= bp[0][0]) return bp[0][1];
    for (var i = 1; i < bp.length; i++) if (x <= bp[i][0]) { var a = bp[i - 1], b = bp[i]; return a[1] + (b[1] - a[1]) * (x - a[0]) / (b[0] - a[0]); }
    return bp[bp.length - 1][1];
  }
  function travelScore(t) { return t ? pw(t.min, t.mode === "transit" ? BP_TRANSIT : BP_DRIVE) : null; }

  // ---- finance facts per complex (finance block if the data has it, else derived from attributes)
  function districtTohuh(it) { var d = it.attributes && it.attributes.district; return d && d.tohuh && d.tohuh.value ? d.tohuh : null; }
  function finOf(it) {
    var f = it.finance;
    if (f && isNum(f.price_eok)) return f;
    var pr = it.attributes && it.attributes.price;
    if (!pr || !isNum(pr.value)) return null;
    var toh = districtTohuh(it);
    // policy_rules: 규제지역 = 토지거래허가구역과 같은 범위; all 53 complexes are in 수도권
    return { price_eok: pr.value, price_size_m2: isNum(pr.size_m2) ? pr.size_m2 : null, sgg_code: it.sgg_code, regulated: !!toh, tohuh: !!toh, sudogwon: true, derived: true };
  }
  function tohuhOf(it) {
    var f = it.finance, d = districtTohuh(it);
    if (f && f.tohuh === false) return null;
    if (f && f.tohuh && typeof f.tohuh === "object") return Object.assign({}, d || {}, f.tohuh);
    if (f && f.tohuh === true) return Object.assign({}, d || {}, f.tohuh_expiry ? { expiry: f.tohuh_expiry } : {});
    return d;
  }
  // same_as: ids of other rows for the same complex (list or single id, possibly mutual) — the row
  // with the lowest id stands for the group in every ranking
  function sameAsList(it) { var x = it.same_as; return (!x ? [] : Array.isArray(x) ? x : [x]).filter(function (id) { return csById[id] && id !== it.id; }); }
  function canonicalId(it) { return [it.id].concat(sameAsList(it)).sort()[0]; }
  function priceBasis(it) { var p = it.attributes && it.attributes.price; return p ? [p.size_m2 ? p.size_m2 + "㎡" : null, p.month, p.kind].filter(Boolean).join(" · ") : ""; }

  // ---- state: purposes, situation (all empty at start), assumptions (defaults from the rule file)
  var FIT = { w: {}, jc: {}, info: null, formOpen: false, section: "rank", onlyOk: null, more: false, save: false, picker: null, netOpen: false };
  function emptySit() {
    return { home: null, marital: null, years: null, kids: null, newborn: false, under7: false, pregnancy: null, dual: false,
      inc1: null, inc2: null, cash: null, debt: null, work1: null, work2: null, freq1: null, freq2: null, maxMin: null };
  }
  var SIT = emptySit();
  function defaultAsm() { return { rate: PR ? PR.mortgage.default_rate_pct : 5, type: "variable", years: PR ? PR.mortgage.maturity_years_max : 30 }; }
  var ASM = defaultAsm();
  function asmEff() {
    var d = defaultAsm();
    return { rate: isNum(ASM.rate) && ASM.rate > 0 ? ASM.rate : d.rate, type: ASM.type || d.type, years: isNum(ASM.years) && ASM.years > 0 ? ASM.years : d.years };
  }
  function capsText(at) {
    var caps = PR.mortgage.caps.filter(function (c) { return c.applies_to_area_types.indexOf(at) >= 0; });
    return caps.map(function (c) { return c.loan_max_eok === null ? "한도 없음" : (c.price_max_eok === null ? c.price_min_eok + "억 초과 " : c.price_max_eok + "억 이하 ") + c.loan_max_eok + "억"; }).join(" · ");
  }
  var STORE_KEY = "apt-finder-v1";
  function persist() {
    try {
      if (!window.localStorage) return;
      if (FIT.save) localStorage.setItem(STORE_KEY, JSON.stringify({ v: 1, sit: SIT, asm: ASM, w: FIT.w, jc: FIT.jc }));
      else localStorage.removeItem(STORE_KEY);
    } catch (e) { /* storage blocked: stay in memory */ }
  }
  (function restore() {
    var raw = null;
    try { raw = window.localStorage ? localStorage.getItem(STORE_KEY) : null; } catch (e) { raw = null; }
    if (!raw) return;
    try {
      var o = JSON.parse(raw), base = emptySit();
      Object.keys(base).forEach(function (k) {
        var v = o.sit ? o.sit[k] : undefined;
        if (v === null || typeof v === "number" || typeof v === "boolean" || (typeof v === "string" && v.length < 80)) SIT[k] = v;
      });
      if (o.asm) {
        if (isNum(o.asm.rate)) ASM.rate = o.asm.rate;
        if (["variable", "periodic", "fixed"].indexOf(o.asm.type) >= 0) ASM.type = o.asm.type;
        if (isNum(o.asm.years)) ASM.years = o.asm.years;
      }
      Object.keys(o.w || {}).forEach(function (k) { if (displayById[k] && (o.w[k] === 1 || o.w[k] === 2)) FIT.w[k] = o.w[k]; });
      Object.keys(o.jc || {}).forEach(function (k) { if (o.jc[k] === true) FIT.jc[k] = true; });
      FIT.save = true;
    } catch (e) { /* ignore a broken entry */ }
  })();
  var PLACE_SLOTS = [["work1", "직장 1", "work"], ["work2", "직장 2", "work"], ["freq1", "자주 가는 곳 1", "freq"], ["freq2", "자주 가는 곳 2", "freq"]];
  function visitorPlaces() {
    return PLACE_SLOTS.filter(function (sl) { return SIT[sl[0]] && hubById[SIT[sl[0]]] && (sl[2] === "work" || HUBS_REAL); }).map(function (sl) {
      return { slot: sl[0], label: sl[1], role: sl[2], hub: hubById[SIT[sl[0]]], id: SIT[sl[0]], w: sl[2] === "work" ? 1 : 0.5 };
    });
  }
  function hasSit() { var b = emptySit(); return Object.keys(b).some(function (k) { return SIT[k] !== b[k]; }); }
  function moneyIn() { return !!PR && (SIT.cash !== null || SIT.inc1 !== null || (SIT.dual && SIT.inc2 !== null)); }
  function onlyOkOn() {
    if (FIT.onlyOk !== null) return FIT.onlyOk;
    return (!!PR && SIT.cash !== null) || (!!SIT.maxMin && visitorPlaces().some(function (x) { return x.role === "work"; }));
  }

  // ---- scoring
  function jcChosen() { return JC.filter(function (j) { return FIT.jc[j.id]; }); }
  function commuteScore(o, neutral, isArea) {
    var places = visitorPlaces();
    if (places.length) {
      var sw = 0, tot = 0, fx = [];
      places.forEach(function (pl) {
        var t = travelOf(o, pl.id), sc = travelScore(t);
        fx.push(pl.hub.name + " " + travelText(t) + (t && t.mode === "drive" ? " (교통량 미반영)" : ""));
        if (sc !== null) { sw += pl.w; tot += pl.w * sc; }
      });
      return { s: sw ? Math.round(tot / sw) : null, facts: fx };
    }
    if (isArea) return { s: null, facts: [] };
    var js = jcChosen();
    if (!js.length && neutral) js = JC;
    if (!js.length) return { s: null, facts: [], pending: true };
    var vals = [], fx2 = [];
    js.forEach(function (j) {
      var v = o.scores && o.scores["commute_" + j.id];
      if (isNum(v)) vals.push(v);
      ((o.facts && o.facts["commute_" + j.id]) || []).forEach(function (f) { fx2.push(f); });
    });
    return { s: vals.length ? Math.round(sum(vals, function (v) { return v; }) / vals.length) : null, facts: fx2 };
  }
  function purposeScore(it, pid, neutral) {
    if (pid === "commute") return commuteScore(it, neutral);
    var v = it.scores ? it.scores[pid] : null;
    return { s: isNum(v) ? v : null, facts: (it.facts && it.facts[pid]) || [] };
  }
  function chosenSet() { var out = []; DISPLAY.forEach(function (p) { if (FIT.w[p.id]) out.push({ pid: p.id, w: FIT.w[p.id] }); }); return out; }
  function rankRows(list, key) {
    var prev = null, rank = 0;
    list.forEach(function (r, i) {
      var sc = r.score === null ? null : Math.round(r.score);
      if (sc === null) { r[key] = null; return; }
      if (sc !== prev) { rank = i + 1; prev = sc; }
      r[key] = rank;
    });
  }
  var FX = null;
  function refreshFX() { FX = CS ? computeFX() : null; return FX; }
  function computeFX() {
    var picks = chosenSet(), neutral = !picks.length;
    var set = neutral ? DISPLAY.map(function (p) { return { pid: p.id, w: 1 }; }) : picks;
    var money = moneyIn(), places = visitorPlaces(), whoCache = {};
    var dupes = {};
    CS_ITEMS.forEach(function (it) { var c = canonicalId(it); if (c !== it.id) (dupes[c] || (dupes[c] = [])).push(it); });
    var rows = CS_ITEMS.filter(function (it) { return canonicalId(it) === it.id; }).map(function (it) {
      var parts = set.map(function (c) { var r = purposeScore(it, c.pid, neutral); return { pid: c.pid, w: c.w, s: r.s, facts: r.facts, pending: !!r.pending }; });
      var have = parts.filter(function (p) { return p.s !== null; });
      var sw = sum(have, function (p) { return p.w; });
      var fin = finOf(it);
      var aff = money && fin ? FIN.evaluate(PR, fin, SIT, asmEff(), whoCache) : null;
      var trav = places.map(function (pl) { return { pl: pl, t: travelOf(it, pl.id) }; });
      var over = SIT.maxMin ? trav.filter(function (x) { return x.pl.role === "work" && x.t && x.t.min > SIT.maxMin; }) : [];
      var st = aff ? aff.best.status : "unknown";
      return { it: it, cx: complexById[it.id] || null, parts: parts, score: sw ? sum(have, function (p) { return p.w * p.s; }) / sw : null,
        missing: parts.length - have.length, pending: parts.some(function (p) { return p.pending; }), fin: fin, aff: aff, trav: trav, over: over,
        pass: (st === "ok" || st === "tight" || st === "unknown") && !over.length, dupes: dupes[it.id] || [], rank: null };
    });
    rows.sort(function (a, b) { return (b.score === null ? -1 : b.score) - (a.score === null ? -1 : a.score) || a.it.name.localeCompare(b.it.name, "ko"); });
    var only = onlyOkOn();
    var shown = only ? rows.filter(function (r) { return r.pass; }) : rows;
    rankRows(rows, "rankAll");
    rankRows(shown, "rank");
    var out = { rows: rows, shown: shown, set: set, picks: picks, neutral: neutral, money: money, places: places, only: only,
      nPass: rows.filter(function (r) { return r.pass; }).length, whoCache: whoCache };
    out.maxP = money && SIT.cash !== null ? maxPrices() : null;
    return out;
  }
  function maxPrices() {
    var out = {};
    ["regulated", "capital_other"].forEach(function (at) {
      var bank = FIN.maxPrice(PR, at, SIT, asmEff()), best = null;
      (PR.policy_loans || []).forEach(function (pl) {
        var p = FIN.maxPrice(PR, at, SIT, asmEff(), pl.id);
        if (p !== null && p > bank + 0.005 && (!best || p > best.p)) best = { id: pl.id, name: pl.name, p: p };
      });
      out[at] = { bank: bank, best: best };
    });
    return out;
  }
  function areaRanking() {
    var picks = chosenSet(), amap = CSM.area_purpose_map || {}, places = visitorPlaces();
    var hasTravel = places.length > 0 && CS_AREAS.some(function (a) { return a.travel; });
    var use = picks.filter(function (c) { return amap[c.pid] || (c.pid === "commute" && hasTravel); });
    var fallback = !use.length;
    if (fallback) use = Object.keys(amap).filter(function (pid) { return displayById[pid]; }).map(function (pid) { return { pid: pid, w: 1 }; });
    var rows = CS_AREAS.map(function (a) {
      var parts = use.map(function (c) {
        if (c.pid === "commute") { var r = commuteScore(a, false, true); return { pid: c.pid, w: c.w, s: r.s, facts: r.facts }; }
        var key = amap[c.pid], v = a.scores ? a.scores[key] : null;
        return { pid: c.pid, w: c.w, s: isNum(v) ? (v - 1) * 25 : null, raw: v, prov: !!(a.score_provisional && a.score_provisional[key]) };
      });
      var have = parts.filter(function (p) { return p.s !== null; }), sw = sum(have, function (p) { return p.w; });
      var nCx = CS_ITEMS.filter(function (it) { return canonicalId(it) === it.id && it.attributes && it.attributes.area_match && it.attributes.area_match.id === a.id; }).length;
      return { a: a, src: areaById[a.id] || a, parts: parts, score: sw ? sum(have, function (p) { return p.w * p.s; }) / sw : null, missing: parts.length - have.length,
        trav: places.map(function (pl) { return { pl: pl, t: travelOf(a, pl.id) }; }), nCx: nCx };
    });
    rows.sort(function (x, y) { return (y.score === null ? -1 : y.score) - (x.score === null ? -1 : x.score) || x.a.name.localeCompare(y.a.name, "ko"); });
    rankRows(rows, "rank");
    return { rows: rows, use: use, fallback: fallback, skipped: picks.filter(function (c) { return use.indexOf(c) < 0; }) };
  }

  // ---- text helpers
  function fmtE(v) {
    var t = fmtNum(Math.abs(v) < 0.005 ? 0 : v, Math.abs(v) >= 10 ? 1 : 2);
    if (t.indexOf(".") >= 0) t = t.replace(/0+$/, "").replace(/\.$/, "");
    return t + "억";
  }
  function fmtMan(v) { return nf0.format(Math.round(v)) + "만원"; }
  function hasBatchim(w) {
    var t = String(w || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
    var c = t.charCodeAt(t.length - 1);
    if (c >= 0xac00 && c <= 0xd7a3) return (c - 0xac00) % 28 !== 0;
    return /[013678]$/.test(t); // 일 삼 육 칠 팔 영 … end in a consonant
  }
  function josa(w, withB, withoutB) { return w + (hasBatchim(w) ? withB : withoutB); }
  function euro(w) {
    var t = String(w || "").trim(), c = t.charCodeAt(t.length - 1);
    if (c >= 0xac00 && c <= 0xd7a3) { var jong = (c - 0xac00) % 28; return w + (jong === 0 || jong === 8 ? "로" : "으로"); }
    return w + "(으)로";
  }
  var AT_LABEL = { regulated: "규제지역", capital_other: "그 밖의 수도권", non_capital: "지방" };
  var STATUS_TEXT = { ok: "가능", tight: "빠듯", short: "부족", unknown: "현금 미입력" };
  function confTag(obj) {
    var c = obj && obj.confidence;
    if (c !== "low" && c !== "medium") return null;
    return h("span", { class: "conf", title: c === "low" ? "2026년 상태를 확인하지 못한 규칙" : "2025년 원문과 2026년 '유지' 보도 또는 2차 자료로 확인한 규칙", text: "확인 수준 낮음" });
  }
  function ruleDate(obj) {
    var d = ((obj && obj.sources) || []).map(function (x) { return x.date; }).filter(Boolean).sort().pop();
    return d || null;
  }
  function ruleMeta(obj, fallbackDate) {
    var d = ruleDate(obj) || fallbackDate || null;
    return h("span", { class: "rmeta" }, d ? h("span", { text: "기준 " + d }) : null, confTag(obj));
  }

  // ---- verdict: two to four plain sentences built from the numbers above
  var BIND_TEXT = {
    dsr: "현금보다 소득 대비 대출 한도(DSR)가 먼저 걸립니다",
    ltv: "대출은 집값 비율(LTV) 한도에서 멈추므로 가진 현금이 관건입니다",
    cap: "가격대별 대출 한도(최대 금액)가 먼저 걸립니다",
    ltv0: "집을 계속 보유한 채 사면 수도권에서는 주택담보대출을 받을 수 없어 현금으로만 사야 합니다"
  };
  function bindDetail(aff) {
    var b = aff.bank;
    if (b.binding === "dsr") return "금리 " + fmtNum(b.dsr.rate, 1) + "%에 스트레스 금리 " + fmtNum(b.dsr.addon, 1) + "%p를 더해 " + b.dsr.years + "년으로 계산하면 은행 대출은 최대 " + fmtE(b.dsrLoan) + "입니다";
    if (b.binding === "cap") return fmtE(aff.price) + " 집은 " + fmtE(b.capLoan) + "까지만 빌릴 수 있습니다";
    if (b.binding === "ltv") return AT_LABEL[b.at] + "에서 " + (b.ltv ? b.ltv.ltv_pct : 0) + "%라 " + fmtE(b.ltvLoan) + "까지입니다" + (b.dsrUnknown ? " (소득을 넣으면 DSR 한도도 계산)" : "");
    return "";
  }
  function statusSentence(best) {
    if (best.status === "ok") return "현금 " + fmtE(best.need) + "이 필요하고 " + fmtE(best.gap) + " 여유가 있습니다";
    if (best.status === "tight") return "현금 " + fmtE(best.need) + "이 필요해 " + fmtE(-best.gap) + "이 모자랍니다(빠듯)";
    if (best.status === "short") return "현금 " + fmtE(best.need) + "이 필요해 " + fmtE(-best.gap) + "이 모자랍니다";
    return "현금 " + fmtE(best.need) + "이 필요합니다(가진 현금을 넣으면 가능 여부를 알려 드립니다)";
  }
  function verdict() {
    var R = FX, out = [], top = R.shown[0], second = R.shown[1];
    if (!top || top.score === null) {
      if (R.only) {
        var cand = R.rows.filter(function (r) { return r.aff && r.aff.best.gap !== null && !r.over.length; });
        cand.sort(function (a, b) { return b.aff.best.gap - a.aff.best.gap; });
        out.push("지금 넣은 조건으로는 " + R.rows.length + "곳 가운데 살 수 있는 곳이 없습니다.");
        if (cand[0]) {
          var n = cand[0];
          out.push(josa(n.it.name, "이", "가") + " 가장 가깝고 " + fmtE(-n.aff.best.gap) + "이 모자랍니다. " + BIND_TEXT[n.aff.bank.binding] + ".");
        } else if (R.rows.some(function (r) { return r.over.length; })) out.push("편도 최대 이동 시간을 넘는 곳이 많습니다. 시간을 늘리거나 직장 선택을 바꿔 보세요.");
        out.push("'살 수 있는 곳만'을 끄면 전체 순위를 흐리게 볼 수 있고, '청약 길'에 새 아파트로 가는 대안이 있습니다.");
      }
      return { lead: null, lines: out };
    }
    var name = top.it.name, area = top.it.area_text ? "(" + top.it.area_text + ")" : "";
    var strong = top.parts.filter(function (p) { return p.s !== null; }).slice().sort(function (a, b) { return b.w * b.s - a.w * a.s; }).slice(0, 2);
    var pre = R.only ? "조건에 맞는 " + R.shown.length + "곳 가운데 " : "";
    if (R.neutral) out.push(pre + josa(name, "을", "를") + " 먼저 보세요. 목적을 고르지 않아 " + R.set.length + "개 기준을 똑같이 본 평균이 " + Math.round(top.score) + "점으로 가장 높습니다" +
      (strong.length ? " — " + strong.map(function (p) { return pLabel(p.pid) + " " + Math.round(p.s) + "점"; }).join(", ") + "." : "."));
    else if (R.picks.length === 1) out.push(pre + josa(name, "을", "를") + " 먼저 보세요. " + pLabel(R.picks[0].pid) + " 점수가 " + Math.round(top.score) + "점으로 가장 높습니다.");
    else out.push(pre + josa(name + area, "을", "를") + " 먼저 보세요. 고른 기준 중 " + strong.map(function (p) { return pLabel(p.pid) + " " + Math.round(p.s) + "점"; }).join(", ") +
      "이 높아 종합 " + Math.round(top.score) + "점으로 1위입니다.");
    if (top.aff) {
      var b = top.aff.best, line = BIND_TEXT[top.aff.bank.binding] + ": " + bindDetail(top.aff) + ".";
      out.push(line.replace(/: \.$/, "."));
      if (b.kind === "policy") out.push(josa(b.name, "을", "를") + " 쓰면 대출이 " + fmtE(b.loan) + "까지 늘어 " + statusSentence(b) + ".");
      else out.push("이 단지는 " + statusSentence(b) + ".");
      if (R.maxP) {
        var m = R.maxP, seg2 = [];
        if (m.regulated) seg2.push("규제지역 " + fmtE(m.regulated.bank));
        if (m.capital_other) seg2.push("그 밖의 수도권 " + fmtE(m.capital_other.bank));
        if (seg2.length) out.push("지금 조건으로 은행 대출을 쓰면 " + seg2.join(", ") + " 집까지 살 수 있습니다" +
          (m.capital_other && m.capital_other.best ? " (" + m.capital_other.best.name + "이면 " + fmtE(m.capital_other.best.p) + ")" : "") + ".");
      }
    } else if (PR && !R.money) out.push("가진 현금과 소득을 넣으면 실제로 살 수 있는지, 어떤 대출 한도가 먼저 걸리는지 함께 계산합니다.");
    if (second && second.score !== null) {
      var both = top.parts.map(function (p, i) { var q = second.parts[i]; return p.s !== null && q && q.s !== null ? { pid: p.pid, d: p.s - q.s } : null; }).filter(Boolean);
      var adv = both.slice().sort(function (a, b2) { return b2.d - a.d; })[0], dis = both.slice().sort(function (a, b2) { return a.d - b2.d; })[0];
      var t = "";
      var sname = second.it.name;
      if (dis && dis.d < -2 && adv && adv.d > 2) t = "2위 " + josa(sname, "은", "는") + " " + pLabel(dis.pid) + "에서 " + Math.round(-dis.d) + "점 앞서지만 " + pLabel(adv.pid) + "에서 " + Math.round(adv.d) + "점 뒤집니다";
      else if (dis && dis.d < -2) t = "2위 " + josa(sname, "은", "는") + " " + pLabel(dis.pid) + "에서 " + Math.round(-dis.d) + "점 앞서지만 종합에서 " + Math.round(top.score - second.score) + "점 낮습니다";
      else t = "2위 " + sname + "보다 고른 기준 모두에서 같거나 높습니다";
      if (top.aff && second.aff) {
        var dp = second.aff.price - top.aff.price;
        if (Math.abs(dp) >= 0.05) t += ". 가격은 2위가 " + fmtE(Math.abs(dp)) + " " + (dp < 0 ? "싸고" : "비싸고") + " " + (second.aff.best.status === top.aff.best.status ? "가능 여부는 같습니다" : "2위는 '" + STATUS_TEXT[second.aff.best.status] + "'입니다");
      }
      out.push(t + ".");
    }
    if (top.trav.length) out.push(name + "에서 " + top.trav.map(function (x) { return x.pl.hub.name + "까지 " + travelText(x.t); }).join(", ") +
      (top.trav.some(function (x) { return x.t && x.t.mode === "drive"; }) ? " (차로 시간은 교통량 미반영)" : "") + ".");
    return { lead: top, lines: out };
  }

  // ---- small UI pieces
  function weightGlyph(w) {
    var svg = s("svg", { width: 20, height: 20, viewBox: "0 0 20 20", "aria-hidden": "true", class: "wg" });
    if (!w) { svg.appendChild(s("circle", { cx: 10, cy: 10, r: 7.5, fill: "none", stroke: cssVar("--text-secondary"), "stroke-width": 1.6 })); return svg; }
    var acc = cssVar("--accent"), ink = cssVar("--accent-ink");
    if (w === 2) svg.appendChild(s("circle", { cx: 10, cy: 10, r: 10.2, fill: "none", stroke: acc, "stroke-width": 1.4 }));
    svg.appendChild(s("circle", { cx: 10, cy: 10, r: w === 2 ? 7.9 : 8, fill: acc }));
    if (w === 1) svg.appendChild(s("path", { d: "M6.2 10.3 l2.6 2.6 l5-5.4", fill: "none", stroke: ink, "stroke-width": 2, "stroke-linecap": "round", "stroke-linejoin": "round" }));
    else { var t = s("text", { x: 10, y: 14.2, "text-anchor": "middle", "font-size": 12, "font-weight": 800, fill: ink }); t.textContent = "2"; svg.appendChild(t); }
    return svg;
  }
  function mbar(v) { return h("span", { class: "mbar", "aria-hidden": "true" }, h("i", { style: "width:" + Math.max(2, Math.round(v || 0)) + "%" })); }
  function affBadge(aff, compact) {
    if (!aff) return null;
    var b = aff.best, st = b.status;
    var g = { ok: "✓", tight: "△", short: "✕", unknown: "₩" }[st];
    var txt = st === "unknown" ? "현금 " + fmtE(b.need) + " 필요" : STATUS_TEXT[st] + (st === "ok" ? (compact ? "" : " · 여유 " + fmtE(b.gap)) : " · " + fmtE(-b.gap) + " 모자람");
    return h("span", { class: "abadge a-" + st }, h("span", { class: "ag", "aria-hidden": "true", text: g }), h("span", { text: txt + (b.kind === "policy" && !compact ? " · 정책대출" : "") }));
  }
  function regBadge(it) {
    var t = tohuhOf(it);
    if (!t) return null;
    return h("span", { class: "rbadge" }, h("span", { class: "ag", "aria-hidden": "true", text: "⚑" }), "규제·토허" + (t.expiry ? " ~" + String(t.expiry).slice(0, 7) : ""));
  }
