    r.vals.forEach(function (v) { svg.appendChild(s("line", { x1: x(v), y1: 12, x2: x(v), y2: 24, class: "tick" })); });
    if (m.kind === "div" && lo < 0 && hi > 0) { svg.appendChild(s("line", { x1: x(0), y1: 8, x2: x(0), y2: 28, class: "zero" })); var z = s("text", { x: x(0), y: 40, "text-anchor": "middle" }); z.textContent = "0"; svg.appendChild(z); }
    svg.appendChild(s("circle", { cx: x(r.v), cy: 18, r: 5.5, class: "me" }));
    var tl = s("text", { x: pad, y: 40 }); tl.textContent = fmtMetric(lo, m); svg.appendChild(tl);
    var tr = s("text", { x: W - pad, y: 40, "text-anchor": "end" }); tr.textContent = fmtMetric(hi, m); svg.appendChild(tr);
