    howto.appendChild(h("span", { class: "only-narrow", text: HOWTO_SHORT }));
    setBasemapNote(isFile ? "file://로 열어 배경지도를 꺼 두었습니다 (타일 서버가 출처 정보 없는 요청을 거부함). 켜 볼 수는 있습니다." : "");
